/* ================= DASHBOARD ================= */
export function Dashboard() {
  const [ctx] = useCtx(); const bal = ctx.bal; const now = today(); const month = now.slice(0, 7); const sess = useSession();
  const issued = ctx.invoices.filter((i) => !['draft', 'pending_approval', 'void'].includes(i.status)); const out = issued.reduce((s, i) => s + (bal[i.id]?.out ?? 0), 0);
  const overdue = issued.filter((i) => bal[i.id]?.out > 0 && i.dueDate < now); const quotes = useRows('quotes'); const bank = useRows('bankTx'); const promises = useRows('promises'); const notes = useRows('notifications');
  const buckets = Object.fromEntries(BUCKETS.map((b) => [b, issued.filter((i) => bal[i.id]?.out > 0 && ageBucket(i.dueDate, now) === b).reduce((s, i) => s + bal[i.id].out, 0)]));
  const tasks: [string, number, string][] = [['Invoices awaiting approval', ctx.invoices.filter((i) => i.status === 'pending_approval').length, '/app/invoices/approvals'], ['Credit notes awaiting approval', ctx.credits.filter((c) => c.status === 'pending').length, '/app/credits/approvals'], ['Quotations awaiting approval', quotes.filter((q) => q.status === 'pending_approval').length, '/app/quotes/approvals'], ['Unapplied receipts', ctx.receipts.filter((r) => receiptUnapplied(r, ctx.allocs) > 0).length, '/app/receipts/unapplied'], ['Unmatched bank rows', bank.filter((b) => b.status === 'unmatched').length, '/app/reconciliation/unmatched'], ['Missed promises to pay', promises.filter((p) => p.status === 'missed').length, '/app/collections/missed'], ['Open disputes', ctx.disputes.filter((d) => ['open', 'under_review'].includes(d.status)).length, '/app/disputes']];
  const max = Math.max(1, ...Object.values(buckets));
  return <><PageHeader title={`Welcome back, ${sess?.name.split(' ')[0]}`} sub={`${ctx.settings.business.legalName} · ${date(now)}`} actions={<><LinkBtn to="/app/quotes/new">New quotation</LinkBtn><LinkBtn to="/app/invoices/new" variant="primary">New invoice</LinkBtn></>} />
    <div className="kpis"><Kpi label="Billed this month" value={<Money v={issued.filter((i) => i.issueDate.startsWith(month)).reduce((s, i) => s + i.total, 0)} />} /><Kpi label="Collected this month" value={<Money v={ctx.receipts.filter((r) => r.date.startsWith(month) && !['reversed', 'refunded'].includes(r.status)).reduce((s, r) => s + r.amount, 0)} />} tone="good" /><Kpi label="Outstanding" value={<Money v={out} />} tone="warn" note={`${issued.filter((i) => bal[i.id]?.out > 0).length} open invoices`} /><Kpi label="Overdue" value={<Money v={overdue.reduce((s, i) => s + bal[i.id].out, 0)} />} tone="bad" note={`${overdue.length} invoices`} /></div>
    <div className="grid g32"><div>
      <Card title="Needs your attention" actions={<LinkBtn to="/app/reviewer-queue" variant="ghost">Reviewer queue</LinkBtn>}>{tasks.every((t) => !t[1]) ? <Empty title="You’re all caught up" /> : <ul style={{ listStyle: 'none', margin: 0, padding: 0 }}>{tasks.map(([l, n, to]) => <li key={l} style={{ display: 'flex', justifyContent: 'space-between', padding: '10px 0', borderBottom: '1px solid #eceff3' }}><Link to={to}>{l}</Link>{n ? <Badge v="open" label={String(n)} /> : <span style={{ color: 'var(--muted)' }}>0</span>}</li>)}</ul>}</Card>
      <Card title="Recent invoices" actions={<LinkBtn to="/app/invoices" variant="ghost">All invoices</LinkBtn>}><DataTable id="dash-inv" rows={[...ctx.invoices].sort((a, b) => b.issueDate.localeCompare(a.issueDate)).slice(0, 6).map((i) => ({ ...i, out: bal[i.id]?.out ?? 0, dstatus: bal[i.id]?.status }))} cols={[{ k: 'number', label: 'Number', render: (r) => <Link to={`/app/invoices/${r.id}`}>{r.number || 'Draft'}</Link> }, { k: 'customer', label: 'Customer', hideMobile: true }, { k: 'total', label: 'Total', kind: 'money' }, { k: 'dstatus', label: 'Status', kind: 'badge' }]} pageSize={6} /></Card></div>
      <div><Card title="Receivables ageing" actions={<LinkBtn to="/app/collections" variant="ghost">Details</LinkBtn>}>{BUCKETS.map((b) => <div className="chart-row" key={b}><span>{b}</span><div className="track"><div className="fill" style={{ width: `${(buckets[b] / max) * 100}%`, background: b === 'Not due' ? '#6b92c0' : b === '90+' ? '#a32626' : '#cb7a2a' }} /></div><Money v={buckets[b]} /></div>)}</Card>
        <Card title="Latest notifications">{notes.length ? <ul className="tl">{notes.slice(0, 4).map((n) => <li key={n.id}><Link to={n.link}>{n.text}</Link><small>{dateTime(n.at)}</small></li>)}</ul> : <Empty title="No notifications" />}</Card></div></div></>;
}

/* ================= MASTERS ================= */
const stateOpts: [string, string][] = [['MH', 'Maharashtra'], ['KA', 'Karnataka'], ['GJ', 'Gujarat'], ['TN', 'Tamil Nadu'], ['DL', 'Delhi'], ['RJ', 'Rajasthan']];
const gstin = (v: string) => /^\d{2}[A-Z]{5}\d{4}[A-Z]\dZ[A-Z0-9]$/.test(v);
const custSpec = (): FieldSpec[] => [{ k: 'name', label: 'Customer name', required: true, half: true }, { k: 'code', label: 'Code', required: true, half: true, example: 'C026' }, { k: 'gstin', label: 'GSTIN', half: true, example: '27AABCN4821K1Z5', help: '15 characters. Leave blank for unregistered customers.' }, { k: 'state', label: 'State (place of supply)', type: 'select', options: stateOpts, required: true, half: true }, { k: 'city', label: 'City', half: true }, { k: 'terms', label: 'Payment terms (days)', type: 'number', min: 0, max: 180, required: true, half: true }, { k: 'creditLimit', label: 'Credit limit', type: 'money', half: true }, { k: 'email', label: 'Accounts email', type: 'email', required: true, half: true }, { k: 'billingAddress', label: 'Billing address', type: 'textarea' }];
const custSave = (v: Row, id?: string) => {
  if (v.gstin && !gstin(v.gstin.toUpperCase())) return { ok: false as const, error: 'GSTIN format looks wrong. Expected 15 characters like 27AABCN4821K1Z5.' };
  const dupe = getState().db.customers.find((c) => c.tenantId === getState().session?.tenantId && c.id !== id && (c.code.toLowerCase() === v.code.toLowerCase() || (v.gstin && c.gstin === v.gstin.toUpperCase())));
  if (dupe) return { ok: false as const, error: `Duplicate: ${dupe.name} already uses that code or GSTIN.` };
  const sn = stateOpts.find((s) => s[0] === v.state)?.[1] ?? v.state; const data = { ...v, gstin: (v.gstin ?? '').toUpperCase(), stateName: sn };
  if (id) update('customers', id, data, 'Customer ' + v.name + ' updated'); else insert('customers', { ...data, status: 'active', accountManager: getState().session!.name }, 'Customer ' + v.name + ' created');
  return { ok: true as const, message: 'Saved. Issued invoices keep the details they were issued with.' };
};
export const CustomersList = () => <ListScreen id="customers" cfg={(c) => ({ coll: 'customers', title: 'Customer directory', sub: 'Master data. Historic invoices keep the details as issued even when a customer is edited.', cols: [{ k: 'name', label: 'Customer', render: (r) => <Link to={`/app/masters/customers/${r.id}`}><b>{r.name}</b></Link> }, { k: 'code', label: 'Code', hideMobile: true }, { k: 'gstin', label: 'GSTIN', hideMobile: true }, { k: 'terms', label: 'Terms', render: (r) => r.terms + ' d', hideMobile: true }, { k: 'out', label: 'Outstanding', kind: 'money' }, { k: 'status', label: 'Status', kind: 'badge' }], map: (r) => ({ ...r, out: c.invoices.filter((i) => i.customerId === r.id).reduce((s, i) => s + (c.bal[i.id]?.out ?? 0), 0) }), filters: [{ k: 'status', label: 'Status', options: ['active', 'on_hold'] }, { k: 'state', label: 'State', options: stateOpts }], link: (r) => `/app/masters/customers/${r.id}`, create: { label: 'Add customer', spec: custSpec(), init: { terms: 30, state: TENANTS.find((t) => t.id === getState().session?.tenantId)!.state }, onSubmit: (v) => custSave(v), draftKey: 'customer' }, edit: { spec: custSpec(), onSubmit: (r, v) => custSave(v, r.id) }, actions: (x) => [{ label: 'Hold', danger: true, show: (r) => r.status === 'active', run: (r) => x.dlg.reason('Put ' + r.name + ' on credit hold', (reason) => { update('customers', r.id, { status: 'on_hold', holdReason: reason }, `Customer ${r.name} put on hold: ${reason}`, true); toast('On hold: new invoices are blocked'); }, { danger: true, confirm: 'Place hold' }) }, { label: 'Release', show: (r) => r.status === 'on_hold', run: (r) => { update('customers', r.id, { status: 'active' }, 'Customer hold released'); toast('Released'); } }], csvName: 'customers' as never })} />;
export function CustomerDetail() {
  const { id } = useParams(); const [ctx, node] = useCtx(); const [tab, setTab] = useState('overview'); const cu = ctx.customers.find((c) => c.id === id); const contacts = useRows('contacts').filter((c) => c.customerId === id); const links = useRows('portalLinks').find((l) => l.customerId === id);
  if (!cu) return <Empty title="Customer not found" action={<LinkBtn to="/app/masters/customers">Back</LinkBtn>} />;
  const invs = ctx.invoices.filter((i) => i.customerId === id).map((i) => ({ ...i, out: ctx.bal[i.id]?.out ?? 0, dstatus: ctx.bal[i.id]?.status })); const out = invs.reduce((s, i) => s + i.out, 0);
  return <><PageHeader title={cu.name} crumbs={[['Customers', '/app/masters/customers'], [cu.name]]} sub={<><Badge v={cu.status} /> · {cu.code} · {cu.city}</>} actions={<><LinkBtn to={`/app/collections/statement/${cu.id}`}>Statement</LinkBtn><LinkBtn to={`/app/invoices/new`} variant="primary">New invoice</LinkBtn></>} />
    <div className="kpis"><Kpi label="Outstanding" value={<Money v={out} />} tone="warn" /><Kpi label="Credit limit" value={<Money v={cu.creditLimit} />} note={out > cu.creditLimit ? 'Over limit' : `${Math.round((out / (cu.creditLimit || 1)) * 100)}% used`} tone={out > cu.creditLimit ? 'bad' : undefined} /><Kpi label="Terms" value={`${cu.terms} days`} /></div>
    <Tabs tabs={[['overview', 'Overview'], ['contacts', 'Contacts'], ['invoices', 'Invoices'], ['bank', 'Payment & bank (restricted)'], ['portal', 'Portal access']]} active={tab} onChange={setTab} />
    {tab === 'overview' && <Card><Dl items={[['GSTIN', cu.gstin || 'Unregistered'], ['Place of supply', cu.stateName], ['Billing address', cu.billingAddress], ['Accounts email', cu.email], ['Collections owner', cu.accountManager], ['Credit hold', cu.status === 'on_hold' ? cu.holdReason : 'No']]} /></Card>}
    {tab === 'contacts' && <Card><DataTable id={'cd-contacts-' + id} rows={contacts} cols={[{ k: 'name', label: 'Name' }, { k: 'role', label: 'Role' }, { k: 'email', label: 'Email', hideMobile: true }, { k: 'billing', label: 'Billing', kind: 'bool' }, { k: 'authorisedToAccept', label: 'Can accept quotes', kind: 'bool' }]} /></Card>}
    {tab === 'invoices' && <Card><DataTable id={'cd-inv-' + id} rows={invs} onRowClick={(r) => ctx.nav(`/app/invoices/${r.id}`)} cols={[{ k: 'number', label: 'Number' }, { k: 'issueDate', label: 'Issued', kind: 'date' }, { k: 'total', label: 'Total', kind: 'money' }, { k: 'out', label: 'Outstanding', kind: 'money' }, { k: 'dstatus', label: 'Status', kind: 'badge' }]} /></Card>}
    {tab === 'bank' && <Card><Notice kind="warn">Payment and bank information is restricted. Changes need approval from a second person.</Notice>{ctx.role === 'staff' ? <Empty title="Restricted" text="Your role cannot view customer payment details." /> : <><Dl items={[['Settlement account', 'HDFC •••• 4821'], ['UPI handle', '•••••@okhdfc'], ['Pending change', cu.bankChange ? 'Yes – awaiting approval' : 'None']]} /><div style={{ marginTop: 12 }}><Button onClick={() => ctx.dlg.reason('Request bank detail change', (reason) => { update('customers', cu.id, { bankChange: true }, 'Customer bank change requested: ' + reason, true); toast('Sent for approval'); }, { label: 'Why is it changing?' })}>Request change…</Button>{cu.bankChange && ctx.role === 'owner' && <Button variant="primary" onClick={() => { update('customers', cu.id, { bankChange: false }, 'Customer bank change approved', true); toast('Approved'); }}>Approve change</Button>}</div></>}</Card>}
    {tab === 'portal' && <Card><Dl items={[['Portal status', <Badge v={links?.active ? 'active' : 'suspended'} label={links?.active ? 'Enabled' : 'Revoked'} />], ['Link created', date(links?.created)], ['Users with access', contacts.filter((c) => c.portal).map((c) => c.email).join(', ')]]} /><div style={{ marginTop: 12 }}>{links && <Button variant={links.active ? 'danger' : 'primary'} onClick={() => { update('portalLinks', links.id, { active: !links.active }, `Portal ${links.active ? 'revoked' : 'restored'} for ${cu.name}`, true); toast(links.active ? 'Portal links and sessions revoked' : 'Portal restored'); }}>{links.active ? 'Revoke portal access' : 'Restore portal access'}</Button>}</div></Card>}{node}</>;
}
export const SuppliersList = () => <ListScreen id="suppliers" cfg={(c) => ({ coll: 'suppliers', title: 'Supplier directory', sub: 'Bank detail changes require second-person approval before any payment.', cols: [{ k: 'name', label: 'Supplier' }, { k: 'gstin', label: 'GSTIN', hideMobile: true }, { k: 'terms', label: 'Terms', render: (r) => r.terms + ' d', hideMobile: true }, { k: 'bank', label: 'Bank (masked)', hideMobile: true }, { k: 'bankChangePending', label: 'Bank change', render: (r) => (r.bankChangePending ? <Badge v="pending" label="Awaiting approval" /> : <Badge v="paid" label="Verified" />) }], create: { label: 'Add supplier', spec: [{ k: 'name', label: 'Supplier name', required: true }, { k: 'gstin', label: 'GSTIN', half: true }, { k: 'terms', label: 'Terms (days)', type: 'number', min: 0, required: true, half: true }, { k: 'email', label: 'Accounts email', type: 'email', half: true }, { k: 'bank', label: 'Bank (name •••• last 4)', half: true }], init: { terms: 30 }, onSubmit: (v) => { if (c.suppliers.some((s) => s.name.toLowerCase() === v.name.trim().toLowerCase())) return { ok: false, error: 'A supplier with that name already exists.' }; insert('suppliers', { ...v, name: v.name.trim(), status: 'active', bankChangePending: false }, 'Supplier added'); return { ok: true, message: 'Added' }; } }, edit: { spec: [{ k: 'name', label: 'Supplier name', required: true }, { k: 'terms', label: 'Terms (days)', type: 'number', min: 0, required: true }, { k: 'email', label: 'Accounts email', type: 'email' }], onSubmit: (r, v) => { update('suppliers', r.id, v, 'Supplier updated'); return { ok: true, message: 'Saved' }; } }, actions: (x) => [{ label: 'Change bank', run: (r) => x.dlg.form('Request bank change – ' + r.name, [{ k: 'bank', label: 'New bank (name •••• last 4)', required: true }, { k: 'verified', label: 'I verified these details with the supplier by phone', type: 'checkbox', required: true }], {}, (v) => { if (!v.verified) return { ok: false, error: 'Confirm that you verified the details.' }; update('suppliers', r.id, { bankChangePending: true, pendingBank: v.bank }, 'Supplier bank change requested', true); return { ok: true, message: 'Payments blocked until approved.' }; }) }] })} />;
export const ContactsList = () => <ListScreen id="contacts" cfg={(c) => ({ coll: 'contacts', title: 'Contacts', sub: 'Billing contacts can differ from service contacts. Only authorised contacts can accept quotations.', cols: [{ k: 'name', label: 'Name' }, { k: 'cname', label: 'Customer', hideMobile: true }, { k: 'role', label: 'Role', hideMobile: true }, { k: 'email', label: 'Email' }, { k: 'billing', label: 'Billing', kind: 'bool' }, { k: 'authorisedToAccept', label: 'Can accept', kind: 'bool', hideMobile: true }, { k: 'portal', label: 'Portal', kind: 'bool', hideMobile: true }], map: (r) => ({ ...r, cname: c.customers.find((x) => x.id === r.customerId)?.name }), filters: [{ k: 'cname', label: 'Customer', options: c.customers.map((x) => x.name) }], create: { label: 'Add contact', spec: contactSpec(c), onSubmit: (v) => { const cu = c.customers.find((x) => x.id === v.customerId); insert('contacts', { ...v }, 'Contact added for ' + cu?.name); return { ok: true, message: 'Added' }; } }, edit: { spec: contactSpec(c), onSubmit: (r, v) => { update('contacts', r.id, v, 'Contact updated'); return { ok: true, message: 'Saved' }; } }, actions: () => [{ label: 'Remove', danger: true, run: (r) => c.dlg.confirm('Remove contact?', `${r.name} will lose portal access.`, () => remove('contacts', r.id, 'Contact removed'), { danger: true, confirm: 'Remove' }) }] })} />;
