export const BranchesList = () => <ListScreen id="branches" cfg={(c) => ({ coll: 'branches', title: 'Branches', sub: 'Branch context is shown in the top bar and filters documents.', cols: [{ k: 'name', label: 'Branch' }, { k: 'city', label: 'City' }, { k: 'gstin', label: 'GSTIN', hideMobile: true }, { k: 'active', label: 'Active', kind: 'bool' }], create: { label: 'Add branch', spec: branchSpec(), onSubmit: (v) => { const sub = getState().db.subscriptions.find((s) => s.tenantId === getState().session?.tenantId); const plan = getState().db.plans.find((p) => p.id === sub?.planId); if (plan && c.branches.length >= plan.branches) return { ok: false, error: `${plan.name} allows ${plan.branches} branches. Upgrade to add more.` }; insert('branches', { ...v, active: true }, 'Branch added'); return { ok: true, message: 'Added' }; } }, edit: { spec: [...branchSpec(), { k: 'active', label: 'Active', type: 'checkbox' }], onSubmit: (r, v) => { update('branches', r.id, v, 'Branch updated'); return { ok: true, message: 'Saved' }; } } })} />;
const branchSpec = (): FieldSpec[] => [{ k: 'name', label: 'Branch name', required: true }, { k: 'city', label: 'City', required: true, half: true }, { k: 'state', label: 'State', type: 'select', options: stateOpts, required: true, half: true }, { k: 'gstin', label: 'Branch GSTIN', half: true }];
export const TaxConfig = () => <ListScreen id="taxes" cfg={() => ({ coll: 'taxes', title: 'Tax configuration', sub: 'GST rates available on lines. Intra-state splits CGST+SGST; inter-state uses IGST. Confirm jurisdiction output rules with a qualified adviser.', cols: [{ k: 'name', label: 'Rate' }, { k: 'rate', label: '%', kind: 'num' }, { k: 'hsnRequired', label: 'HSN/SAC required', kind: 'bool' }, { k: 'active', label: 'Enabled', kind: 'bool' }], edit: { label: 'Configure', spec: [{ k: 'hsnRequired', label: 'HSN/SAC required', type: 'checkbox' }, { k: 'active', label: 'Enabled', type: 'checkbox' }], onSubmit: (r, v) => { update('taxes', r.id, v, 'Tax rate configured', true); return { ok: true, message: 'Saved' }; } } })} />;
export const NumberingList = () => <ListScreen id="numbering" cfg={() => ({ coll: 'numbering', title: 'Document numbering', sub: 'Sequences reset each financial year. Next numbers can only move forward.', cols: [{ k: 'name', label: 'Document' }, { k: 'prefix', label: 'Prefix' }, { k: 'fy', label: 'FY', hideMobile: true }, { k: 'nextSeq', label: 'Next number', kind: 'num' }, { k: 'padding', label: 'Digits', kind: 'num', hideMobile: true }, { k: 'preview', label: 'Next looks like' }], map: (r) => ({ ...r, preview: `${r.prefix}/${r.fy}/${String(r.nextSeq).padStart(r.padding, '0')}` }), edit: { spec: [{ k: 'prefix', label: 'Prefix', required: true, half: true }, { k: 'padding', label: 'Digits', type: 'number', min: 3, max: 8, required: true, half: true }, { k: 'nextSeq', label: 'Next number', type: 'number', min: 1, required: true }], onSubmit: (r, v) => { if (v.nextSeq < r.nextSeq) return { ok: false, error: `Next number cannot go backwards (currently ${r.nextSeq}); that would risk duplicate numbers.` }; update('numbering', r.id, v, `Numbering for ${r.name} changed`, true); return { ok: true, message: 'Saved' }; } } })} />;
export const PeriodSettings = () => <ListScreen id="period-settings" cfg={(c) => ({ coll: 'periods', title: 'Period settings', sub: 'Financial periods and locks. Locked periods refuse backdated issue, void, reversal and adjustment.', cols: [{ k: 'name', label: 'Period' }, { k: 'start', label: 'From', kind: 'date' }, { k: 'end', label: 'To', kind: 'date' }, { k: 'locked', label: 'State', render: (r) => <Badge v={r.locked ? 'paid' : 'open'} label={r.locked ? 'Locked' : 'Open'} /> }], actions: (x) => [{ label: 'Lock', show: (r) => !r.locked, run: (r) => { update('periods', r.id, { locked: true }, `Period ${r.name} locked`, true); toast('Locked'); } }, { label: 'Unlock', danger: true, show: (r) => r.locked && c.role === 'owner', run: (r) => x.dlg.reason('Unlock ' + r.name, (reason) => { update('periods', r.id, { locked: false }, `Period ${r.name} unlocked: ${reason}`, true); toast('Unlocked'); }, { danger: true, confirm: 'Unlock' }) }] })} />;

