  return <><PageHeader title="Memberships" sub="Businesses you belong to. Switching workspace is always explicit." crumbs={[['Users and access', '/app/users'], ['Memberships']]} />
    <Card><DataTable id="memberships" rows={ws} cols={[{ k: 'tn', label: 'Business', value: (r) => r.tenant.name }, { k: 'role', label: 'Your role', render: (r) => cap(r.role) }, { k: 'tenantId', label: 'Current', render: (r) => (r.tenantId === sess.tenantId ? <Badge v="active" label="Current" /> : '') }]} rowActions={[{ label: 'Switch', show: (r) => r.tenantId !== sess.tenantId, run: (r) => { const x = switchWorkspace(r.id); notify(x, 'Workspace switched'); if (x.ok) nav('/app'); } }]} /></Card></>;
