export function RoleEditor() {
  const roles = useRows('roleDefs'); const [ctx] = useCtx(); const editable = ctx.role === 'owner';
  return <><PageHeader title="Role editor" sub="Choose what each role can do. Sensitive permissions are highlighted." crumbs={[['Users and access', '/app/users'], ['Roles']]} />
    {!editable && <Notice kind="warn">Only the owner can change roles.</Notice>}
    <Card><div className="perm-grid"><table><thead><tr><th>Role</th>{PERMISSIONS.map((p) => <th key={p} className={SENSITIVE.includes(p) ? 'sens' : ''} title={SENSITIVE.includes(p) ? 'Sensitive permission' : ''}>{cap(p)}{SENSITIVE.includes(p) ? ' ⚑' : ''}</th>)}</tr></thead><tbody>{roles.filter((r) => r.name !== 'customer').map((r) => <tr key={r.id}><td><b>{cap(r.name)}</b></td>{PERMISSIONS.map((p) => <td key={p}><input type="checkbox" aria-label={`${r.name} can ${p}`} checked={r.permissions.includes(p)} disabled={!editable || r.name === 'owner'} onChange={(e) => notify(setRolePermission(r.name, p, e.target.checked), 'Updated')} /></td>)}</tr>)}</tbody></table></div><p style={{ color: 'var(--muted)', fontSize: 13 }}>Business, branch and record-ownership filters apply to lists, search, downloads, reports and background jobs regardless of role.</p></Card></>;
}
