export const AuditTrail = () => <ListScreen id="audit" cfg={() => ({ coll: 'audit', title: 'Audit trail', sub: 'Sensitive changes are logged with who, what and when. Entries cannot be edited.', cols: [{ k: 'at', label: 'When', kind: 'datetime' }, { k: 'actor', label: 'Who' }, { k: 'action', label: 'What' }, { k: 'sensitive', label: 'Sensitive', render: (r) => (r.sensitive ? <Badge v="warn" label="Sensitive" /> : '') , hideMobile: true }], filters: [{ k: 'sensitive', label: 'Type', options: [['true', 'Sensitive only'], ['false', 'Routine']], value: (r) => String(!!r.sensitive) }, { k: 'actor', label: 'Who', options: ['Meera Kulkarni', 'Rohan Iyer', 'Anita Shah'] }], defaultSort: ['at', 'desc'], pageSize: 15 })} />;
export const SupportAccess = () => <ListScreen id="support-access" cfg={() => ({ coll: 'supportAccess', title: 'Support access approval', sub: 'Platform support can only look at your data when you approve, for a limited time, and every view is audited.', cols: [{ k: 'requestedBy', label: 'Requested by' }, { k: 'reason', label: 'Reason' }, { k: 'scope', label: 'Scope', hideMobile: true }, { k: 'expires', label: 'Expires', kind: 'date', hideMobile: true }, { k: 'status', label: 'Status', kind: 'badge' }], actions: (x) => [{ label: 'Approve', show: (r) => r.status === 'pending', run: (r) => { update('supportAccess', r.id, { status: 'approved', approvedBy: getState().session!.name }, 'Support access approved', true); toast('Approved until ' + date(r.expires)); } }, { label: 'Deny', danger: true, show: (r) => r.status === 'pending', run: (r) => x.dlg.reason('Deny support access', (reason) => { update('supportAccess', r.id, { status: 'denied', reason: r.reason + ' (denied: ' + reason + ')' }, 'Support access denied', true); toast('Denied'); }, { danger: true, confirm: 'Deny' }) }, { label: 'Revoke', danger: true, show: (r) => r.status === 'approved', run: (r) => { update('supportAccess', r.id, { status: 'denied' }, 'Support access revoked', true); toast('Revoked'); } }], allow: () => false })} />;

/* ================= SETUP & PLAN ================= */
export function Welcome() {
  const st = useSettings(); const cl = st.setup.checklist as Record<string, boolean>; const items: [string, string, string][] = [['business', 'Business details', '/app/setup/business'], ['billing', 'Billing details (GSTIN, bank)', '/app/setup/billing'], ['plan', 'Choose a plan', '/app/setup/plan'], ['branches', 'Set up branches', '/app/setup/branches'], ['branding', 'Brand your documents', '/app/setup/branding'], ['team', 'Invite your team', '/app/setup/team'], ['import', 'Import customers and opening balances', '/app/setup/import'], ['review', 'Review setup', '/app/setup/review'], ['activate', 'Activate', '/app/setup/activate']];
  const done = items.filter((i) => cl[i[0]]).length;
  return <><PageHeader title="Welcome checklist" sub={`${done} of ${items.length} steps complete. Progress is saved automatically.`} />
    <Card><div className="bar" style={{ marginBottom: 12 }}><i style={{ width: `${(done / items.length) * 100}%`, background: 'var(--good)' }} /></div>{items.map(([k, l, to]) => <div key={k} className={'check' + (cl[k] ? ' done' : '')}><span className="circ">{cl[k] ? '✓' : ''}</span><Link to={to} style={{ flex: 1 }}>{l}</Link><Button variant="ghost" onClick={() => { saveSettings('setup', { checklist: { ...cl, [k]: !cl[k] } }, 'Setup step toggled'); }}>{cl[k] ? 'Mark not done' : 'Mark done'}</Button></div>)}</Card></>;
}
