  return <><PageHeader title="Team invitation" crumbs={[['Setup', '/app/setup/welcome'], ['Team']]} /><Card title="Invite someone"><FormView spec={inviteSpec(ctx)} init={{ role: 'staff' }} submit="Send invitation" onSubmit={(v) => { const r = inviteMember(v); if (r.ok) toast(r.message!); return r; }} /></Card><Card title={`Team (${members.length})`}><DataTable id="team" rows={members} cols={[{ k: 'name', label: 'Name' }, { k: 'email', label: 'Email', hideMobile: true }, { k: 'role', label: 'Role', render: (r) => cap(r.role) }, { k: 'status', label: 'Status', kind: 'badge' }]} /></Card></>;
