export function Activation() {
  const st = useSettings(); const cl = st.setup.checklist; const ready = ['business', 'billing', 'plan', 'branches'].every((k) => cl[k]);
  return <><PageHeader title="Activation" crumbs={[['Setup', '/app/setup/welcome'], ['Activate']]} />{st.setup.activated ? <Notice kind="good">Your workspace is active. Customers can receive invoices and use the portal.</Notice> : <Notice kind={ready ? 'info' : 'warn'}>{ready ? 'Everything required is complete.' : 'Complete business, billing, plan and branches first.'}</Notice>}
    <Card><Button variant="primary" disabled={!ready || st.setup.activated} onClick={() => { saveSettings('setup', { activated: true, checklist: { ...cl, activate: true } }, 'Workspace activated'); toast('Workspace activated'); }}>{st.setup.activated ? 'Already active' : 'Activate workspace'}</Button>{st.setup.activated && <Button variant="danger" style={{ marginLeft: 8 }} onClick={() => { saveSettings('setup', { activated: false }, 'Workspace deactivated'); }}>Deactivate (demo)</Button>}</Card></>;
}
function usePlanData() { const sub = useRows('subscriptions')[0]; const plans = useRows('plans'); const plan = plans.find((p) => p.id === sub?.planId); return { sub, plan, plans: plans.filter((p) => p.active) }; }
export function PlanSelection() {
  const { sub, plans } = usePlanData(); const nav = useNavigate(); const [cycle, setCycle] = useState(sub?.cycle ?? 'monthly');
  return <><PageHeader title="Plan selection" crumbs={[['Plan', '/app/plan'], ['Choose']]} actions={<div className="pill-row"><Button variant={cycle === 'monthly' ? 'primary' : 'secondary'} onClick={() => setCycle('monthly')}>Monthly</Button><Button variant={cycle === 'yearly' ? 'primary' : 'secondary'} onClick={() => setCycle('yearly')}>Yearly (save ~17%)</Button></div>} />
    <div className="grid g3">{plans.map((p) => <div key={p.id} className={'price' + (p.id === 'growth' ? ' pop' : '')}><h3>{p.name}{sub?.planId === p.id && <> <Badge v="active" label="Current" /></>}</h3><div className="amt">{moneyShort(cycle === 'monthly' ? p.monthly : p.yearly)}<small style={{ fontSize: 14, color: 'var(--muted)' }}>/{cycle === 'monthly' ? 'mo' : 'yr'}</small></div><p>{p.blurb}</p><ul><li>{p.users} users</li><li>{p.branches} branches</li><li>{p.entities} legal entit{p.entities > 1 ? 'ies' : 'y'}</li></ul><Button variant="primary" disabled={sub?.planId === p.id && sub?.cycle === cycle} onClick={() => nav(`/app/setup/checkout?plan=${p.id}&cycle=${cycle}`)}>{sub?.planId === p.id ? 'Change billing cycle' : 'Select ' + p.name}</Button></div>)}</div><p style={{ color: 'var(--muted)' }}>Prices exclude GST. Plan versions and effective dates preserve historical billing.</p></>;
}
export function Checkout() {
  const [sp] = useSearchParams(); const nav = useNavigate(); const { sub, plans } = usePlanData(); const pm = useRows('paymentMethods'); const plan = plans.find((p) => p.id === (sp.get('plan') ?? sub?.planId)); const cycle = sp.get('cycle') ?? sub?.cycle ?? 'monthly'; const [method, setMethod] = useState(''); const [err, setErr] = useState('');
  if (!plan) return <Empty title="Choose a plan first" action={<LinkBtn to="/app/setup/plan">Plans</LinkBtn>} />;
  const price = cycle === 'monthly' ? plan.monthly : plan.yearly; const gst = Math.round(price * 0.18);
  return <><PageHeader title="Checkout" crumbs={[['Plan', '/app/plan'], ['Checkout']]} />
    <div className="grid g32"><Card title="Payment method">{pm.map((m) => <label key={m.id} className="check" style={{ cursor: 'pointer' }}><input type="radio" name="pm" checked={(method || pm.find((x) => x.primary)?.id) === m.id} onChange={() => setMethod(m.id)} /><span style={{ flex: 1 }}>{m.kind} · {m.label}{m.mandate && ' (autopay mandate)'}</span></label>)}{err && <Notice kind="bad">{err}</Notice>}<p style={{ color: 'var(--muted)', fontSize: 13 }}>The payment provider is simulated in this build; no card is charged.</p></Card>
      <Card title="Order summary"><Dl items={[['Plan', `${plan.name} (v${plan.version})`], ['Billing', cycle], ['Price', money(price)], ['GST 18%', money(gst)], ['Due today', money(price + gst)]]} /><div className="form-f"><Button variant="primary" onClick={() => { const r = changePlan(plan.id, cycle); if (!r.ok) return setErr(r.error); saveSettings('setup', { checklist: { ...getState().settings[getState().session!.tenantId].setup.checklist, plan: true } }); toast(r.message!); nav('/app/plan'); }}>Pay {money(price + gst)} and switch</Button></div></Card></div></>;
}
export function CurrentPlan() {
  const { sub, plan } = usePlanData(); const subInv = useRows('subInvoices');
  if (!sub || !plan) return <Empty title="No subscription" />;
  return <><PageHeader title="Current plan" crumbs={[['Plan']]} actions={<><LinkBtn to="/app/plan/upgrade">Upgrade</LinkBtn><LinkBtn to="/app/plan/downgrade">Downgrade</LinkBtn></>} />
    {sub.status === 'cancelling' && <Notice kind="warn">Cancellation scheduled. Access continues until {date(sub.cancelAt)}. <Link to="/app/plan/export">Export your data</Link> before then.</Notice>}{sub.renewalFailure && <Notice kind="bad">Last renewal failed. You have a {sub.graceDays}-day grace period. <Link to="/app/plan/renewal-failures">Fix payment</Link></Notice>}
    <div className="kpis"><Kpi label="Plan" value={`${plan.name} v${sub.planVersion}`} /><Kpi label="Billing" value={cap(sub.cycle)} /><Kpi label="Renews" value={date(sub.renewsOn)} /><Kpi label="Next charge" value={<Money v={sub.cycle === 'monthly' ? plan.monthly : plan.yearly} />} note="+ GST" /></div>
    <Card title="Recent subscription invoices"><DataTable id="plan-inv-mini" rows={subInv.slice(0, 3)} cols={[{ k: 'number', label: 'Number' }, { k: 'date', label: 'Date', kind: 'date' }, { k: 'amount', label: 'Amount', kind: 'money' }, { k: 'status', label: 'Status', kind: 'badge' }]} /></Card></>;
}
export function PlanUsage() {
  const { sub, plan } = usePlanData(); const members = useRows('members').filter((m) => m.status !== 'suspended'); const branches = useRows('branches'); const invs = useRows('invoices');
  if (!sub || !plan) return null; const meters: [string, number, number][] = [['Users', members.length, plan.users], ['Branches', branches.length, plan.branches], ['Legal entities', 1, plan.entities], ['Invoices this month', invs.filter((i) => i.issueDate?.startsWith(today().slice(0, 7)) && i.number).length, 300], ['Storage (MB)', sub.storageMb, 5000]];
  return <><PageHeader title="Usage" sub="Entitlements are checked when you add users, branches or entities." crumbs={[['Plan', '/app/plan'], ['Usage']]} /><Card>{meters.map(([l, u, m]) => { const p = Math.min(100, (u / m) * 100); return <div key={l} className="chart-row" style={{ gridTemplateColumns: '170px 1fr 120px' }}><span>{l}</span><div className="track" role="progressbar" aria-valuenow={u} aria-valuemax={m} aria-label={l}><div className="fill" style={{ width: p + '%', background: p >= 100 ? 'var(--bad)' : p > 80 ? '#cb7a2a' : undefined }} /></div><span className="num">{u} / {m}</span></div>; })}</Card></>;
}
export function Upgrades() { const { sub, plans } = usePlanData(); const nav = useNavigate(); const cur = plans.findIndex((p) => p.id === sub?.planId); return <><PageHeader title="Upgrades" crumbs={[['Plan', '/app/plan'], ['Upgrade']]} />{plans.slice(cur + 1).length ? <div className="grid g2">{plans.slice(cur + 1).map((p) => <div className="price" key={p.id}><h3>{p.name}</h3><div className="amt">{moneyShort(p.monthly)}<small>/mo</small></div><p>{p.blurb}</p><p style={{ color: 'var(--muted)', fontSize: 13 }}>Takes effect immediately; the unused part of your current period is credited.</p><Button variant="primary" onClick={() => nav(`/app/setup/checkout?plan=${p.id}&cycle=${sub?.cycle}`)}>Upgrade to {p.name}</Button></div>)}</div> : <Empty title="You’re on the top plan" />}</>; }
export function Downgrades() {
  const { sub, plans, plan } = usePlanData(); const nav = useNavigate(); const members = useRows('members').filter((m) => m.status !== 'suspended'); const branches = useRows('branches'); const cur = plans.findIndex((p) => p.id === sub?.planId);
  return <><PageHeader title="Downgrades" sub="We tell you exactly what must be resolved before a smaller plan can apply." crumbs={[['Plan', '/app/plan'], ['Downgrade']]} />{plans.slice(0, Math.max(0, cur)).length ? <div className="grid g2">{plans.slice(0, cur).map((p) => { const ou = Math.max(0, members.length - p.users), ob = Math.max(0, branches.length - p.branches); return <div className="price" key={p.id}><h3>{p.name}</h3><div className="amt">{moneyShort(p.monthly)}<small>/mo</small></div><p>{p.users} users · {p.branches} branches</p>{ou || ob ? <Notice kind="warn">Resolve first: {ou ? `suspend ${ou} user(s)` : ''}{ou && ob ? ' and ' : ''}{ob ? `deactivate ${ob} branch(es)` : ''}.</Notice> : <Notice kind="good">Nothing to resolve.</Notice>}<Button disabled={!!(ou || ob)} onClick={() => { const r = changePlan(p.id, sub!.cycle); notify(r); if (r.ok) nav('/app/plan'); }}>Downgrade to {p.name}</Button></div>; })}</div> : <Empty title="No smaller plan" />}<p style={{ color: 'var(--muted)' }}>Current: {plan?.name}. Downgrades apply immediately in this demo; in production they apply at the end of the period.</p></>;
}
export const PaymentMethods = () => <ListScreen id="payment-methods" cfg={(c) => ({ coll: 'paymentMethods', title: 'Payment methods', sub: 'Used for your subscription only. Customer receipts are separate from platform billing.', cols: [{ k: 'kind', label: 'Type' }, { k: 'label', label: 'Details' }, { k: 'expires', label: 'Expires', hideMobile: true }, { k: 'primary', label: 'Primary', kind: 'bool' }, { k: 'mandate', label: 'Autopay', kind: 'bool' }], create: { label: 'Add method', spec: [{ k: 'kind', label: 'Type', type: 'select', options: ['Card', 'UPI AutoPay', 'NetBanking mandate'], required: true, half: true }, { k: 'label', label: 'Details', required: true, half: true, example: 'Visa •••• 1111' }, { k: 'expires', label: 'Expires (MM/YYYY)', half: true }], onSubmit: (v) => { insert('paymentMethods', { ...v, primary: false, mandate: v.kind !== 'Card' }, 'Payment method added', ); return { ok: true, message: 'Added' }; } }, actions: (x) => [{ label: 'Make primary', show: (r) => !r.primary, run: (r) => { getState().db.paymentMethods.filter((m) => m.tenantId === r.tenantId).forEach((m) => update('paymentMethods', m.id, { primary: m.id === r.id })); toast('Primary updated'); } }, { label: 'Remove', danger: true, show: (r) => !r.primary, run: (r) => x.dlg.confirm('Remove payment method?', r.label, () => remove('paymentMethods', r.id, 'Payment method removed'), { danger: true, confirm: 'Remove' }) }] })} />;
export const SubInvoices = () => <ListScreen id="sub-invoices" cfg={() => ({ coll: 'subInvoices', title: 'Subscription invoices', sub: 'What Ledgerline charges your business. Separate from the invoices you issue to your customers.', cols: [{ k: 'number', label: 'Number' }, { k: 'date', label: 'Date', kind: 'date' }, { k: 'plan', label: 'Plan', hideMobile: true }, { k: 'amount', label: 'Amount (+GST)', kind: 'money' }, { k: 'status', label: 'Status', kind: 'badge' }], actions: () => [{ label: 'Download', run: (r) => { const u = URL.createObjectURL(new Blob([`Ledgerline subscription invoice ${r.number}\nPlan: ${r.plan}\nAmount: ${money(r.amount)} + GST\nDate: ${r.date}\n`], { type: 'text/plain' })); const a = document.createElement('a'); a.href = u; a.download = r.number.replace(/\//g, '-') + '.txt'; a.click(); } }] })} />;
export function RenewalFailures() {
  const { sub } = usePlanData(); const [ctx] = useCtx();
  return <><PageHeader title="Renewal failures" crumbs={[['Plan', '/app/plan'], ['Renewals']]} />{sub?.renewalFailure ? <Notice kind="bad">Renewal on {date(sub.renewsOn)} failed. Service continues for a {sub.graceDays}-day grace period, then moves to read-only.</Notice> : <Notice kind="good">No failed renewals.</Notice>}
    <Card><div className="pill-row"><Button variant="primary" disabled={!sub?.renewalFailure} onClick={() => notify(retryRenewal())}>Retry payment now</Button><Button onClick={() => ctx.nav('/app/plan/payment-methods')}>Update payment method</Button><Button onClick={() => { update('subscriptions', sub!.id, { renewalFailure: true }, 'Simulated renewal failure'); toast('Simulated a failed renewal', 'info' as never); }}>Simulate a failure (demo)</Button></div></Card></>;
}
export function CancelPlan() {
  const { sub } = usePlanData(); const [ctx, node] = useCtx();
  return <><PageHeader title="Cancellation" crumbs={[['Plan', '/app/plan'], ['Cancel']]} />{sub?.status === 'cancelling' ? <><Notice kind="warn">Cancellation is scheduled for {date(sub.cancelAt)}.</Notice><Button onClick={() => { update('subscriptions', sub.id, { status: 'active', cancelAt: '' }, 'Cancellation withdrawn', true); toast('Cancellation withdrawn'); }}>Keep my subscription</Button></> : <Card><p>Cancelling stops renewal at the end of the paid period ({date(sub?.renewsOn)}). You keep read access and export rights afterwards; issued invoices remain available per your retention settings.</p><Button variant="danger" onClick={() => ctx.dlg.reason('Cancel subscription', (reason) => { const r = cancelSubscription(reason); notify(r); return r.ok; }, { label: 'Why are you leaving?', confirm: 'Schedule cancellation', danger: true })}>Cancel subscription…</Button></Card>}{node}</>;
}
export function ExportClosure() {
  const [ctx] = useCtx(); const st = ctx.settings; const [confirmText, setConfirmText] = useState(''); const db = getState().db; const t = getState().session!.tenantId;
  const download = () => { const out: Record<string, unknown> = {}; ['customers', 'suppliers', 'items', 'invoices', 'quotes', 'receipts', 'allocations', 'credits', 'disputes', 'bills', 'supplierPayments', 'expenses', 'audit'].forEach((c) => (out[c] = db[c].filter((r) => r.tenantId === t))); const u = URL.createObjectURL(new Blob([JSON.stringify(out, null, 2)], { type: 'application/json' })); const a = document.createElement('a'); a.href = u; a.download = `ledgerline-export-${today()}.json`; a.click(); saveSettings('closure', { exportRequested: true }, 'Full data export downloaded'); toast('Export downloaded'); };
  return <><PageHeader title="Export and closure" crumbs={[['Plan', '/app/plan'], ['Export and closure']]} />
    <Card title="1. Export your data"><p>Download everything in your workspace as JSON (documents, balances, allocations, audit). Individual tables are also available as CSV on each screen.</p><Button variant="primary" icon="download" onClick={download}>Download full export</Button>{st.closure.exportRequested && <p style={{ color: 'var(--good)' }}>✓ Export downloaded</p>}</Card>
    <Card title="2. Close the workspace"><Notice kind="warn">Closure schedules deletion after your retention period ({st.retention?.invoiceAccessDays ?? 90} days of read-only invoice access). It cannot be undone after that.</Notice>{st.closure.closureRequested ? <><Notice kind="bad">Closure requested.</Notice><Button onClick={() => { saveSettings('closure', { closureRequested: false }, 'Closure request withdrawn'); }}>Withdraw closure request</Button></> : <><label className="fld" style={{ maxWidth: 360 }}><span>Type the business name to confirm</span><input value={confirmText} onChange={(e) => setConfirmText(e.target.value)} placeholder={st.business.tradeName} /></label><div style={{ marginTop: 12 }}><Button variant="danger" disabled={confirmText !== st.business.tradeName || !st.closure.exportRequested} onClick={() => { saveSettings('closure', { closureRequested: true }, 'Workspace closure requested', ); toast('Closure requested'); }}>Request closure</Button>{!st.closure.exportRequested && <small style={{ marginLeft: 8, color: 'var(--muted)' }}>Download an export first.</small>}</div></>}</Card></>;
}
